    const near = (x, hrs) => x.league === lg && Math.abs(new Date(x.kickoff) - at) < hrs * 3600e3, nm = (x, t) => lsSame(x, t.displayName) || lsSame(x, t.shortDisplayName) || lsSame(x, t.name);
