function levelOf(xp) { let i = 0; LEVELS.forEach(([, t], k) => { if (xp >= t) i = k; }); const next = LEVELS[i + 1]; return { i, name: LEVELS[i][0], from: LEVELS[i][1], to: next ? next[1] : null, next: next ? next[0] : null }; }
