function afterUpset(ok, prob, streak, lg) { reward(10 + (ok ? 15 + 5 * Math.min(streak, 5) : 0), "Spot the upset", (p) => { mark(p, lg, null); if (ok && prob <= 0.12) unlock(p, "upset"); }); if (ok) Board.submit({ game: "upset", league: S.code, score: streak }); }
