const dfDays = (p) => p.dfDone || {};
function dfStreak(p) { let s = 0; const now = Date.now(), L = dfDays(p); for (let k = 0; k < 400; k++) { const key = new Date(now - k * 864e5).toISOString().slice(0, 10); if (L[key]) s++; else if (k > 0) break; } return s; }
