  async setNick(nick) { const t = await this.token(); if (!t) return { error: "Please sign in first." }; try { const r = await fetch(`${Board.cfg.url}/rest/v1/rpc/set_nickname`, { method: "POST", headers: this.hdr(t), body: JSON.stringify({ p_nick: nick }) }); const j = await r.json(); if (j === "ok") return { ok: true }; return { error: j === "taken" ? "That nickname is taken. Try another." : j === "invalid" ? "Use 3 to 16 letters, numbers, spaces, dots, dashes or underscores." : this.errText(j) }; } catch (e) { return { error: "Could not reach the server." }; } },
