  if (p.city || p.bc) cl.push(["Birthplace", `Born in ${p.city ? p.city + ", " : ""}${p.bc || p.nat}`, flagOf(p.bc || p.nat)]);
  if (p.h) cl.push(["Build", `${p.h} cm tall${p.foot ? `, ${p.foot}-footed` : ""}`]);
  cl.push(["Age", `${a} years old (born ${p.dob.slice(0, 4)})`]);
